import heapq

class MaxPriorityQueue:
    def __init__(self):
        self._heap = []
        self._counter = 0

    def push(self, item, priority: int) -> None:
        # Use negative priority for max-heap via heapq (min-heap)
        heapq.heappush(self._heap, (priority, self._counter, item))  # bug: should be -priority
        self._counter += 1

    def pop(self):
        neg_priority, _, item = heapq.heappop(self._heap)
        return neg_priority  # bug: should return item

    def peek(self):
        neg_priority, _, item = self._heap[0]
        return neg_priority  # bug: should return item

    def __len__(self):
        return len(self._heap)
